function encodeCell(value: string): string {
  const formulaLike =
    /^[\t\r\n]/u.test(value) ||
    /^[\s\u0000-\u001f\u007f]*[=+@-]/u.test(value);

  const safe = formulaLike ? `'${value}` : value;
  return `"${safe.replace(/"/g, '""')}"`;
